-- --------------------------------------------------------------------------------------
-- 2. DateDim (날짜) 테이블 삽입
-- Author: 강리현
-- Contribution: 날짜 차원 테이블의 SQL 자동 생성 로직 (재귀 CTE) 및 공휴일 데이터 업데이트
-- --------------------------------------------------------------------------------------
WITH RECURSIVE dates AS (
  SELECT DATE('2024-01-01') AS d           -- 시작일
  UNION ALL
  SELECT DATE_ADD(d, INTERVAL 1 DAY)       -- 하루씩 더하기
  FROM dates
  WHERE d < '2024-12-31'                   -- 12월 31일까지 반복
)
SELECT 
  d,                  -- 2024-01-01 ~ 2024-12-31
  MONTH(d),           -- d에서 월 추출 (1~12)
  DAY(d)              -- d에서 일 추출 (1~31)
FROM dates
ON DUPLICATE KEY UPDATE           -- 중복이면 기존 row를 갱신, 없는 날짜만 새로 추가
  month = VALUES(month),
  day = VALUES(day);

-- is_holiday 초기화
UPDATE DateDim
SET is_holiday = 0
WHERE date_id BETWEEN '2024-01-01' AND '2024-12-31';

-- is_holiday 표시
UPDATE DateDim
SET is_holiday = 1
WHERE date_id IN (
  '2024-01-01',
  '2024-02-09','2024-02-10','2024-02-11','2024-02-12',
  '2024-03-01',
  '2024-05-05','2024-05-06','2024-05-15',
  '2024-06-06',
  '2024-08-15',
  '2024-09-16','2024-09-17','2024-09-18',
  '2024-10-03','2024-10-09',
  '2024-12-25'
);


