-- --------------------------------------------------------------------------------------


-- --------------------------------------------------------------------------------------
-- 8. TravelIndex (여행 적합 지수) 테이블 삽입
-- Author: 김연수
-- Contribution: 여행 지수 산정 로직(가중치/CASE WHEN) 설계 및 최종 계산 쿼리 작성
-- --------------------------------------------------------------------------------------
    region_code,
    date_id,
    travel_index_score,
    temp_score,
    clear_score,
    dry_score
)
SELECT
    scores.region_code,
    scores.date_id,

    -- Travel Index 계산
    (0.50 * temp_score) + (0.30 * clear_score) + (0.20 * dry_score) AS travel_index_score,

    -- 개별 점수 계산
    temp_score,
    clear_score,
    dry_score

FROM (
    SELECT
        t.region_code,
        t.date_id,

        -- Temp_Score
        CASE
            WHEN t.avg_temp BETWEEN 15 AND 25 THEN 100
            WHEN t.avg_temp BETWEEN 10 AND 30 THEN 80
            WHEN t.avg_temp BETWEEN 5 AND 35 THEN 50
            ELSE 20
        END AS temp_score,

        -- Clear_Score
        CASE
            WHEN a.pm10 <= 15 AND r.cloud_cover <= 3 THEN 100
            WHEN a.pm10 <= 35 AND r.cloud_cover <= 7 THEN 70
            ELSE 30
        END AS clear_score,

        -- Dry_Score
        CASE
            WHEN r.daily_rainfall = 0 AND r.wind_speed < 4 THEN 100
            WHEN r.daily_rainfall < 5 AND r.wind_speed < 7 THEN 80
            ELSE 40
        END AS dry_score

    FROM Temperature t
    JOIN AirQuality a
        ON t.region_code = a.region_code
        AND t.date_id = a.date_id
    JOIN Rain r
        ON t.region_code = r.region_code
        AND t.date_id = r.date_id
) AS scores

ON DUPLICATE KEY UPDATE
    travel_index_score = VALUES(travel_index_score),
    temp_score = VALUES(temp_score),
    clear_score = VALUES(clear_score),
    dry_score = VALUES(dry_score);

